from urllib.parse import urlsplit, urlunsplit, parse_qsl


def _host_matches(host: str | None, match_value: str) -> bool:
    if host is None:
        return False

    host = host.lower()
    match_value = match_value.lower()

    if match_value.startswith("*."):
        base_domain = match_value[2:]
        # ドメインそのものは除外し、厳密なサブドメインのみ許可
        return host.endswith("." + base_domain) and host != base_domain

    return host == match_value


def _replace_host(parsed, new_host: str):
    """Replace only the hostname while preserving userinfo and port."""
    netloc = parsed.netloc

    userinfo = ""
    hostport = netloc

    if "@" in netloc:
        userinfo, _, hostport = netloc.rpartition("@")
        userinfo += "@"

    # 元のポート指定を保持する
    port_suffix = ""
    if hostport.startswith("["):
        # IPv6 address
        closing_bracket = hostport.find("]")
        if (
            closing_bracket != -1
            and len(hostport) > closing_bracket + 1
            and hostport[closing_bracket + 1] == ":"
        ):
            port_suffix = hostport[closing_bracket + 1 :]
    elif ":" in hostport:
        # 通常の hostname:port
        port_suffix = hostport[hostport.rfind(":") :]

    # IPv6 の場合は角括弧を付ける
    if ":" in new_host and not new_host.startswith("["):
        new_host = f"[{new_host}]"

    new_netloc = userinfo + new_host + port_suffix
    return parsed._replace(netloc=new_netloc)


def apply_rewrite_rules(rules, urls):
    results = []

    for url in urls:
        parsed = urlsplit(url)
        matched_rule = None

        for rule in rules:
            match_type = rule["match_type"]
            match_value = rule["match_value"]

            if match_type == "path_prefix":
                if parsed.path.startswith(match_value):
                    matched_rule = rule
                    break

            elif match_type == "host":
                if _host_matches(parsed.hostname, match_value):
                    matched_rule = rule
                    break

            elif match_type == "query_param":
                query_params = parse_qsl(
                    parsed.query,
                    keep_blank_values=True,
                )
                if any(name == match_value for name, _ in query_params):
                    matched_rule = rule
                    break

            else:
                raise ValueError(f"Unknown match_type: {match_type}")

        # どのルールにも適合しない場合
        if matched_rule is None:
            results.append(url)
            continue

        action = matched_rule["action"]

        if action == "block":
            results.append(None)
            continue

        action_value = matched_rule["action_value"]

        if action == "strip_prefix":
            path = parsed.path
            if path.startswith(action_value):
                path = path[len(action_value) :]
            if path == "":
                path = "/"

            parsed = parsed._replace(path=path)

        elif action == "redirect_host":
            parsed = _replace_host(parsed, action_value)

        elif action == "add_query_param":
            query = parsed.query
            if query:
                query += "&" + action_value
            else:
                query = action_value

            parsed = parsed._replace(query=query)

        else:
            raise ValueError(f"Unknown action: {action}")

        results.append(urlunsplit(parsed))

    return results
